from pathlib import Path
import json,csv,html
ROOT=Path(__file__).resolve().parents[1]
D=json.load(open(ROOT/'data/healthy-home-index.json')); cities=D['cities']; meta=D['meta']

def esc(x):return html.escape(str(x))
def delta(c):
 d=c.get('change',0) or 0
 if d>0:return f'<span class="delta up">▲ {d:.1f}</span>'
 if d<0:return f'<span class="delta down">▼ {abs(d):.1f}</span>'
 return '<span>—</span>'
def header(title,desc,canonical='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="https://homenhealthy.com{canonical}"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body><header class="top"><div class="wrap"><a class="brand" href="/"><span>HNH</span>HomeNHealthy.com</a><nav class="nav"><a href="/rankings/">Index</a><a href="/movers/">Movers</a><a href="/components/air-quality/">Air</a><a href="/components/water/">Water</a><a href="/methodology/">Methodology</a><a href="/data-download/">Data</a></nav></div></header>'''
def footer():return '''<footer class="foot"><div class="wrap"><div class="footerlinks"><a href="/rankings/">Healthy Home Index</a><a href="/movers/">Index Movers</a><a href="/methodology/">Methodology</a><a href="/data-download/">Download Data</a><a href="/home-wellness/">Home Wellness</a></div><p>HomeNHealthy is a geographic environmental-data resource. It is not a home inspection, medical assessment, water-quality test or indoor-air measurement.</p></div></footer></body></html>'''
def write(rel,s):
 p=ROOT/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def banner():
 if meta.get('starter'):
  return '<div class="wrap"><div class="notice"><b>Starter preview dataset.</b> Run the GitHub <b>Update Healthy Home Index and deploy</b> workflow to replace preview values with EPA, NOAA and Census data.</div></div>'
 src=meta.get('sources',{});partial=[]
 if src.get('airnow',0)<40:partial.append('AirNow')
 if src.get('echo_states',0)<40:partial.append('EPA drinking water')
 if src.get('noaa_cities',0)<50:partial.append('NOAA climate')
 if src.get('acs_cities',0)<50:partial.append('Census housing')
 if partial:return '<div class="wrap"><div class="notice"><b>Live index with partial source coverage.</b> Prior values were preserved where live retrieval was unavailable: '+', '.join(partial)+'.</div></div>'
 return ''
def row(c):
 return f'''<tr data-city-row><td class="rank">#{c['rank']}</td><td><b><a href="/cities/{c['slug']}/">{esc(c['city'])}, {c['state']}</a></b></td><td class="score">{c['score']:.1f}</td><td>{c['air'].get('aqi','—')}</td><td>{c['water'].get('compliance_pct','—')}%</td><td>{c['climate'].get('moisture_pressure','—')}</td><td>{c['housing'].get('median_year_built','—')}</td><td>{delta(c)}</td></tr>'''

best=cities[:8];avg=round(sum(c['score'] for c in cities)/len(cities),1);src=meta.get('sources',{})
lookup=''.join(f'<a data-lookup-city="{(c["city"]+" "+c["state"]).lower()}" href="/cities/{c["slug"]}/"></a>' for c in cities)
h=header('HomeNHealthy — U.S. Healthy Home Index','A continuously refreshed geographic index combining current air quality, drinking-water compliance, climate moisture pressure and housing-age data.')+banner()+f'''<main><section class="hero"><div class="wrap"><div class="eyebrow">U.S. residential environmental intelligence</div><h1>How healthy is the environment around your home?</h1><p>HomeNHealthy combines public environmental and housing datasets into a transparent city-level index. It measures geography—not the condition of an individual house.</p><form class="lookup" data-home-lookup><input placeholder="Search a city, e.g. Austin or Denver" aria-label="Search city"><button class="btn">Find your city</button></form><div style="display:none">{lookup}</div></div></section><section class="section"><div class="wrap"><div class="eyebrow">Current index</div><h2>75 cities. Four public-data signals.</h2><p class="sub">Scores combine an AirNow AQI snapshot, EPA drinking-water compliance, NOAA climate moisture pressure and Census housing-age data. Each component is labeled as a proxy and documented in the methodology.</p><div class="metric-grid"><div class="metric"><small>Indexed cities</small><b>{len(cities)}</b></div><div class="metric"><small>Average score</small><b>{avg}</b></div><div class="metric"><small>Data refresh</small><b>2×</b><span>weekly</span></div><div class="metric"><small>Last generated</small><b style="font-size:22px">{meta.get('generated','—')}</b></div></div><div class="tablebox"><table><thead><tr><th>Rank</th><th>City</th><th>Score</th><th>AQI now</th><th>Water</th><th>Moisture</th><th>Median build</th><th>Move</th></tr></thead><tbody>{''.join(row(c) for c in best)}</tbody></table></div><p><a class="btn light" href="/rankings/">View all 75 cities →</a></p></div></section><section class="section alt"><div class="wrap"><div class="eyebrow">What the score is actually measuring</div><h2>Environmental context, not a diagnosis.</h2><div class="cards"><div class="card"><div class="mini">30% of score</div><h3>Air quality snapshot</h3><p>Current AirNow AQI for the closest reporting area. This is a current outdoor environmental snapshot, not a claim about indoor air.</p><a href="/components/air-quality/">How air data works →</a></div><div class="card"><div class="mini">30% of score</div><h3>Drinking-water compliance</h3><p>Share of active community water systems in the state without a current health-based violation in EPA ECHO/SDWIS.</p><a href="/components/water/">How water data works →</a></div><div class="card"><div class="mini">20% of score</div><h3>Climate moisture pressure</h3><p>A climate proxy derived from NOAA warm-season temperature and precipitation normals. It is not a mold measurement.</p><a href="/components/moisture/">How climate data works →</a></div><div class="card"><div class="mini">20% of score</div><h3>Housing-age proxy</h3><p>Census median year built. Older housing can be excellent; this represents age-related maintenance context only.</p><a href="/components/housing-age/">How housing data works →</a></div></div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">Designed to be cited</div><h2>Download the underlying index.</h2><p class="sub">Journalists, researchers and publishers may cite the HomeNHealthy U.S. Healthy Home Index with attribution. The dataset includes component values, score, rank and source status.</p><p><a class="btn" href="/data-download/">Download CSV / JSON</a></p></div><div class="report"><h3>Update status</h3><dl><dt>AirNow city coverage</dt><dd>{src.get('airnow',0)}/{len(cities)}</dd><dt>EPA water state coverage</dt><dd>{src.get('echo_states',0)}/51</dd><dt>NOAA city coverage</dt><dd>{src.get('noaa_cities',0)}/{len(cities)}</dd><dt>Census city coverage</dt><dd>{src.get('acs_cities',0)}/{len(cities)}</dd></dl></div></div></section></main>'''+footer();write('index.html',h)

h=header('U.S. Healthy Home Index Rankings | HomeNHealthy','Rank 75 U.S. cities using the HomeNHealthy geographic environmental index.','/rankings/')+banner()+'''<section class="cityhero"><div class="wrap"><div class="eyebrow">National rankings</div><h1>U.S. Healthy Home Index</h1><p class="sub">Search the current city-level geographic index.</p></div></section><section class="section"><div class="wrap"><div class="searchbar"><input data-city-search placeholder="Filter cities or states"></div><div class="tablebox"><table><thead><tr><th>Rank</th><th>City</th><th>Score</th><th>AQI now</th><th>Water</th><th>Moisture</th><th>Median build</th><th>Move</th></tr></thead><tbody>'''+''.join(row(c) for c in cities)+'''</tbody></table></div></div></section>'''+footer();write('rankings/index.html',h)

movers=sorted(cities,key=lambda c:abs(c.get('change',0) or 0),reverse=True)
h=header('Healthy Home Index Movers | HomeNHealthy','See which indexed cities moved most since the previous HomeNHealthy data refresh.','/movers/')+banner()+'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Freshness ledger</div><h1>What changed this update?</h1><p class="sub">Movement is driven mainly by current AirNow conditions and newly published source data. It does not mean an individual home became healthier or less healthy.</p></div></section><section class="section"><div class="wrap"><div class="tablebox"><table><thead><tr><th>City</th><th>Current score</th><th>Change</th><th>Current AQI</th><th>Water compliance</th></tr></thead><tbody>'''+''.join(f'<tr><td><b><a href="/cities/{c["slug"]}/">{esc(c["city"])}, {c["state"]}</a></b></td><td>{c["score"]:.1f}</td><td>{delta(c)}</td><td>{c["air"].get("aqi","—")}</td><td>{c["water"].get("compliance_pct","—")}%</td></tr>' for c in movers[:30])+'''</tbody></table></div></div></section>'''+footer();write('movers/index.html',h)

for c in cities:
 air,wat,cli,hou=c['air'],c['water'],c['climate'],c['housing'];bars=''.join(f'<span style="height:{max(5,min(100,(m.get("prcp_in",0) or 0)*14))}%" data-v="{m.get("prcp_in",0)} in"></span>' for m in c.get('monthly',[]))
 h=header(f'{c["city"]}, {c["state"]} Healthy Home Score | HomeNHealthy',f'Environmental and housing context for {c["city"]}, {c["state"]}: air quality, drinking-water compliance, climate moisture pressure and housing age.',f'/cities/{c["slug"]}/')+banner()+f'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Healthy Home Index · #{c['rank']} nationally</div><h1>{esc(c['city'])}, {c['state']}</h1><div class="bigscore">{c['score']:.1f}<span style="font:16px Arial"> / 100</span></div><p>Geographic environmental score · {delta(c)} since prior refresh</p></div></section><main class="section"><div class="wrap"><div class="component-grid"><div class="component"><div class="mini">Air snapshot · 30%</div><div class="num">{air['score']:.0f}</div><div>AQI: <b>{air.get('aqi','—')}</b></div><div class="bar"><i style="width:{air['score']}%"></i></div></div><div class="component"><div class="mini">Water compliance · 30%</div><div class="num">{wat['score']:.0f}</div><div><b>{wat.get('compliance_pct','—')}%</b> no current health violation</div><div class="bar"><i style="width:{wat['score']}%"></i></div></div><div class="component"><div class="mini">Climate moisture · 20%</div><div class="num">{cli['score']:.0f}</div><div>Pressure index: <b>{cli.get('moisture_pressure','—')}</b></div><div class="bar"><i style="width:{cli['score']}%"></i></div></div><div class="component"><div class="mini">Housing age · 20%</div><div class="num">{hou['score']:.0f}</div><div>Median year built: <b>{hou.get('median_year_built','—')}</b></div><div class="bar"><i style="width:{hou['score']}%"></i></div></div></div><div class="split"><div><h2>Environmental context</h2><p>These values describe public datasets for the surrounding geography; they do not measure indoor air, tap water, mold, lead, radon or the condition of a particular building.</p><div class="callout"><b>Current air:</b> {esc(air.get('reporting_area','Closest AirNow reporting area'))}. AirNow observations are outdoor ambient conditions and can change rapidly.</div><h3>Warm-season moisture pressure</h3><p>The climate component combines NOAA May–September average temperature and precipitation. Higher warm, wet conditions raise the proxy; building envelope, ventilation and indoor humidity can differ substantially.</p><div class="chartrow">{bars}</div><p class="data-note">Bars show monthly precipitation from the climate record used for this city.</p></div><aside class="report"><h3>Source ledger</h3><dl><dt>Air source</dt><dd>{esc(air.get('source','—'))}</dd><dt>Water source</dt><dd>{esc(wat.get('source','—'))}</dd><dt>Climate source</dt><dd>{esc(cli.get('source','—'))}</dd><dt>Housing source</dt><dd>{esc(hou.get('source','—'))}</dd><dt>Generated</dt><dd>{meta.get('generated','—')}</dd></dl></aside></div><p style="margin-top:30px"><a class="btn light" href="/states/{c['state'].lower()}/">View {esc(c['state_name'])} cities →</a></p></div></main>'''+footer();write(f'cities/{c["slug"]}/index.html',h)

states={}
for c in cities:states.setdefault(c['state'],[]).append(c)
for st,arr in states.items():
 arr=sorted(arr,key=lambda x:x['score'],reverse=True);name=arr[0]['state_name'];avg=sum(x['score'] for x in arr)/len(arr)
 body=''.join(f'<tr><td>#{i}</td><td><b><a href="/cities/{c["slug"]}/">{esc(c["city"])}</a></b></td><td>{c["score"]:.1f}</td><td>{c["air"].get("aqi","—")}</td><td>{c["water"].get("compliance_pct","—")}%</td><td>{c["climate"].get("moisture_pressure","—")}</td><td>{c["housing"].get("median_year_built","—")}</td></tr>' for i,c in enumerate(arr,1))
 h=header(f'{name} Healthy Home Index | HomeNHealthy',f'Compare indexed cities in {name} using air, water, climate and housing context.',f'/states/{st.lower()}/')+banner()+f'''<section class="cityhero"><div class="wrap"><div class="eyebrow">State profile</div><h1>{name}</h1><p class="sub">{len(arr)} indexed cit{'y' if len(arr)==1 else 'ies'} · average score {avg:.1f}</p></div></section><section class="section"><div class="wrap"><div class="tablebox"><table><thead><tr><th>State rank</th><th>City</th><th>Score</th><th>AQI</th><th>Water</th><th>Moisture</th><th>Housing year</th></tr></thead><tbody>{body}</tbody></table></div></div></section>'''+footer();write(f'states/{st.lower()}/index.html',h)

component_pages={'air-quality':('Air Quality Snapshot','The air component uses the current peak Air Quality Index reported by the closest AirNow reporting area. AirNow recommends its nationwide file products for maintaining a database of reporting-area observations. This is outdoor ambient air, not an indoor-air measurement.','30%'),'water':('Drinking-Water Compliance','The water component uses EPA ECHO / SDWIS counts of active community water systems and the subset with a current health-based drinking-water violation. It is calculated at the state level because public-water service territories often cross municipal boundaries.','30%'),'moisture':('Climate Moisture Pressure','The climate component uses NOAA 1991–2020 monthly normals. Warm-season average temperature and precipitation are combined into a transparent moisture-pressure proxy. It does not measure indoor humidity, leaks or mold.','20%'),'housing-age':('Housing-Age Maintenance Proxy','The housing component uses the Census ACS median year structure built for the city/place. Newer scores higher only as a maintenance-age proxy. An older well-maintained home can be substantially healthier than a newer poorly maintained home.','20%')}
for slug,(ttl,body,weight) in component_pages.items():
 h=header(f'{ttl} | HomeNHealthy',f'How HomeNHealthy uses {ttl.lower()} in the U.S. Healthy Home Index.',f'/components/{slug}/')+f'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Index component · {weight}</div><h1>{ttl}</h1></div></section><section class="section"><div class="wrap split"><div><h2>What it measures</h2><p>{body}</p><div class="callout"><b>Interpretation rule:</b> HomeNHealthy scores geographic context. None of these components should replace property-specific testing, inspection or professional advice.</div><p><a class="btn light" href="/methodology/">See complete methodology →</a></p></div><aside class="report"><h3>Current coverage</h3><dl><dt>Indexed cities</dt><dd>{len(cities)}</dd><dt>Refresh cadence</dt><dd>Mon + Thu</dd><dt>Data download</dt><dd><a href="/data-download/">CSV / JSON</a></dd></dl></aside></div></section>'''+footer();write(f'components/{slug}/index.html',h)

h=header('Methodology | HomeNHealthy','Methodology and limitations for the HomeNHealthy U.S. Healthy Home Index.','/methodology/')+'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Transparent scoring</div><h1>Methodology</h1><p class="sub">The index intentionally separates measurable geography from property-specific claims.</p></div></section><section class="section"><div class="wrap"><div class="report"><h2>Index formula</h2><p><b>30% Air snapshot + 30% drinking-water compliance + 20% climate moisture pressure + 20% housing-age maintenance proxy.</b></p><h3>Air</h3><p>AirNow current reporting-area AQI is converted to a 0–100 component score. Current AQI is volatile and is the main reason rankings can move between updates.</p><h3>Water</h3><p>EPA ECHO/SDWIS is queried for active community water systems by state and for systems with current health-based violations. It does not test water at an individual tap.</p><h3>Climate</h3><p>NOAA 1991–2020 monthly station normals provide warm-season temperature and precipitation. These produce a climate moisture-pressure proxy, not a mold probability model.</p><h3>Housing age</h3><p>Census ACS B25035_001E provides median year structure built for a city/place. Housing age is only a maintenance-age proxy and is not evidence that older buildings contain a particular hazard.</p><h3>Missing data</h3><p>When a source temporarily fails, the updater preserves the prior observed value and marks source coverage. Missing live observations are never replaced with newly invented values.</p><h3>Rankings</h3><p>The score is an editorial composite. Different weights would produce different rankings, so component values are published alongside the overall score.</p></div></div></section>'''+footer();write('methodology/index.html',h)

h=header('Download Healthy Home Index Data | HomeNHealthy','Download HomeNHealthy city-level environmental index data as CSV or JSON.','/data-download/')+'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Open citation dataset</div><h1>Download the index</h1><p class="sub">Publishers may cite the HomeNHealthy U.S. Healthy Home Index with attribution and a link to HomeNHealthy.com.</p></div></section><section class="section"><div class="wrap cards"><div class="card"><h3>CSV</h3><p>Flat table with ranking and component values.</p><a class="btn" href="/data/healthy-home-index.csv">Download CSV</a></div><div class="card"><h3>JSON</h3><p>Complete source metadata and city records.</p><a class="btn" href="/data/healthy-home-index.json">Download JSON</a></div></div></section>'''+footer();write('data-download/index.html',h)

# The only external InHouse link in the generated site.
h=header('Home Wellness Equipment | HomeNHealthy','Context on home wellness equipment and the retailer recommended by HomeNHealthy.','/home-wellness/')+'''<section class="cityhero"><div class="wrap"><div class="eyebrow">Separate from the environmental index</div><h1>Home wellness equipment</h1><p class="sub">HomeNHealthy measures environmental context around a home. Equipment such as saunas and cold plunges is a separate purchasing decision and is not part of the Healthy Home Score.</p></div></section><section class="section"><div class="wrap split"><div><h2>Recommended retailer</h2><p>For homeowners separately researching premium home wellness equipment, our recommended retailer is InHouse Wellness. This recommendation does not affect city rankings, source selection or index methodology.</p><p><a class="btn" href="https://inhousewellness.com/">Visit InHouse Wellness →</a></p></div><aside class="report"><h3>Editorial separation</h3><p>The HomeNHealthy index contains no retailer or product-price variable. The recommendation is intentionally kept outside the scoring system.</p></aside></div></section>'''+footer();write('home-wellness/index.html',h)

with open(ROOT/'data/healthy-home-index.csv','w',newline='') as f:
 w=csv.writer(f);w.writerow(['rank','city','state','score','current_aqi','water_compliance_pct','moisture_pressure','median_year_built','change'])
 for c in cities:w.writerow([c['rank'],c['city'],c['state'],c['score'],c['air'].get('aqi'),c['water'].get('compliance_pct'),c['climate'].get('moisture_pressure'),c['housing'].get('median_year_built'),c.get('change',0)])
urls=['/','/rankings/','/movers/','/methodology/','/data-download/','/home-wellness/']+[f'/components/{s}/' for s in ['air-quality','water','moisture','housing-age']]+[f'/cities/{c["slug"]}/' for c in cities]+[f'/states/{st.lower()}/' for st in sorted({c['state'] for c in cities})]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://homenhealthy.com{u}</loc><lastmod>{meta.get("generated","")}</lastmod></url>' for u in urls)+'</urlset>')
